// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property() public {
        string memory returned = c.version();
        assertTrue(keccak256(bytes(returned)) == keccak256(bytes("1.0.0")), "version must return '1.0.0'");
    }
}

contract InvMutTest {
    C public c;

    constructor(C _c) {
        c = _c;
    }

    function test(address caller, uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) external {
        bool isDepositor = caller == 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;
        vm.prank(caller);
        c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar);
        assert(isDepositor || c.number() != _number);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) public payable {
        require(true);
        bool reverted;
        try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) { reverted = false; } catch { reverted = true; }
        assert(!reverted || msg.sender != 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(address caller) public {
        bool reverted;
        (reverted, ) = address(c).call(abi.encodePacked(bytes4(keccak256("setL1BlockValues(uint64,uint64,uint256,bytes32,uint64,bytes32,uint256,uint256)")), uint64(1), uint64(2), uint256(3), bytes32(uint256(4)), uint64(5), bytes32(uint256(6)), uint256(7), uint256(8)));
        assert(!reverted);
    }
}

contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }
    function test(bytes32 _hash1, bytes32 _hash2) external {
        bool firstRevert;
        try c.setL1BlockValues(0,0,0,_hash1,0,bytes32(0),0,0) { firstRevert = false; } catch { firstRevert = true; }
        bool secondRevert;
        try c.setL1BlockValues(0,0,0,_hash2,0,bytes32(0),0,0) { secondRevert = false; } catch { secondRevert = true; }
        assert(!firstRevert == !secondRevert);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(true);
        bool reverted;
        try c.setL1BlockValues(0, 0, 0, bytes32(0), 0, bytes32(0), 0, 0) { reverted = false; } catch { reverted = true; }
        assert(caller != 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001 ? reverted == true : reverted == false);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) public {
        // The depositor account is a constant, so we prank as that address
        address depositor = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;
        bytes32 expectedBatcherHash = _batcherHash;

        // Call setL1BlockValues as the depositor
        vm.prank(depositor);
        (bool ok, ) = address(c).call(
            abi.encodeWithSelector(
                c.setL1BlockValues.selector,
                _number,
                _timestamp,
                _basefee,
                _hash,
                _sequenceNumber,
                _batcherHash,
                _l1FeeOverhead,
                _l1FeeScalar
            )
        );

        // If the call succeeded, batcherHash must equal the provided argument.
        // In the reference, the call succeeds for any input; the buggy version always reverts (ok == false).
        // we use ok as a boolean flag from try/catch and check the expected equality condition only when ok is true.
        bytes32 actualBatcherHash = c.batcherHash();
        bool condition = (ok && actualBatcherHash == expectedBatcherHash) || !ok;
        assertTrue(condition);
    }
}
